INSERT INTO pgmigrations (name, run_on)
SELECT '20261114130000_add_standardized_question_translations', NOW()
WHERE to_regclass('public.pgmigrations') IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM pgmigrations WHERE name = '20261114130000_add_standardized_question_translations');
